#!/usr/bin/env python3
"""Generate five inactive, synthetic n8n starter kits without touching the original eight."""
from __future__ import annotations
import json, shutil, uuid
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "automation-kits"
SRC = ROOT / "scripts/source-assets/leadgen-engine-export.zip"
TMP = ROOT / ".extended-kit-source"
COMMON = """# {title}

This is an **inactive n8n starter template**, not a deployed agent. It runs with synthetic inputs through a Manual Trigger and Code nodes so a client can inspect validation and an action draft without sending anything.

## Configuration required

- No credentials, outbound communications, production schedules, real customer data, or live provider connections are included.
- Production requires client-owned source systems, approved provider adapters, credentials in n8n Credentials, consent/authorization, security review, and a named human owner for every review path.
- Provider names and documentation links in `api-requirements.json` are planning references only; add no key values to this kit.
- A persistent idempotency store is required in production. Demo flags are not durable production deduplication.

## Run the demo

1. Import a JSON file from `workflows/` into vanilla n8n.
2. Keep the workflow inactive and click Execute Workflow; Manual Trigger starts the synthetic input.
3. Inspect the preparation, validation, and draft/human-handoff Code nodes.
4. Replace only the preparation payload or add an approved adapter; never bypass validation or approval.
5. Before activation, complete consent, privacy/security, credential, idempotency, error, monitoring, and human-approval review.

## Safety contract

All outputs are drafts. No send, filing, payment, booking, transfer, hosting, or external write occurs. Missing, conflicting, stale, opt-out, duplicate, over-capacity, or high-impact data becomes `NEEDS_HUMAN_REVIEW`. Source-confirmed slots, rates, dates, identity, and owner-approved settings are never invented.

## n8n references

These starters use current n8n JSON import/export and built-in Code concepts. See the [Code node guide](https://docs.n8n.io/build/code-in-n8n/using-the-code-node), [Webhook node guide](https://docs.n8n.io/integrations/builtin/core-nodes/n8n-nodes-base.webhook), and [workflow import/export guide](https://docs.n8n.io/build/manage-workflows/export-and-import).

## Contents

- `workflows/*.json` — inactive importable starters; no credentials or live endpoints.
- `quick-start.md`, `api-requirements.json`, `config-template.json` — setup and client particulars.
- `schemas.json`, `prompts.md`, `sample-payloads.json`, `tests.json` — contracts and synthetic fixtures.
"""

def dump(p: Path, x): p.write_text(json.dumps(x, indent=2, ensure_ascii=False)+"\n", encoding="utf-8")
def js_prepare(payload, slug):
    return "const input = %s; const correlation_id = input.correlation_id || 'DEMO-%s'; return [{json:{...input, correlation_id, _demo:true, _scenario:'%s'}}];" % (json.dumps(payload,separators=(',',':')), slug.upper(), slug)
def js_logic(kind):
    common = "const d=$input.first().json; const fail=(reason)=>({status:'NEEDS_HUMAN_REVIEW',review_required:true,reason,correlation_id:d.correlation_id,action_draft:null});"
    bodies = {
      'realestate-normalize': "const missing=['source','name','contact','enquiry_text'].filter(k=>!String(d[k]||'').trim()); const opted=d.opt_out===true; const review=missing.length>0||opted; return [{json:{...d,_validation:{status:review?'NEEDS_HUMAN_REVIEW':'READY',missing,opted_out:opted,reason:opted?'Opt-out received':missing.length?'Required channel fields missing':'Normalized Meta/WhatsApp/voice lead'}}}];",
      'realestate-viewing': "const ok=(d._validation?.status==='READY'||d.lead_validated===true)&&d.broker&&d.listing_source_confirmed===true&&d.viewing_slot?.source_confirmed===true&&d.staff_approval===true; return [{json:{...d,status:ok?'DRAFT_ONLY':'NEEDS_HUMAN_REVIEW',review_required:!ok,reason:ok?'Source-confirmed slot and staff approval present':'Require source-confirmed listing/slot and broker approval',action_draft:ok?{broker_assignment:d.broker,viewing_request:{slot:d.viewing_slot,status:'DRAFT'}}:null}}];",
      'realestate-followup': "const repeats=Number(d.followup_count||0); const ok=d.opt_out!==true&&repeats<Number(d.max_followups||3)&&d.duplicate_found!==true; return [{json:{...d,status:ok?'DRAFT_ONLY':'NEEDS_HUMAN_REVIEW',review_required:!ok,reason:ok?'Capped repeat and opt-out checks passed':'Opt-out, duplicate, or repeat cap blocks follow-up',action_draft:ok?{message:'Draft only: a broker will follow up with source-confirmed details.',attempt:repeats+1}:null}}];",
      'voice-intake': "const missing=['provider_event_id','summary','language','consent_status'].filter(k=>!String(d[k]||'').trim()); const disclosed=d.disclosure_confirmed===true; const ok=!missing.length&&disclosed&&d.consent_status==='granted'; return [{json:{...d,status:ok?'DRAFT_ONLY':'NEEDS_HUMAN_REVIEW',review_required:!ok,reason:ok?'Provider summary and disclosure/consent confirmed':'Missing provider summary, consent, language, or disclosure',action_draft:ok?{summary:d.summary,language:d.language,disclosure:'Use client-approved disclosure',owner:d.owner}:null}}];",
      'voice-transfer': "const ok=d.transfer_destination&&d.owner&&d.transfer_approval===true; return [{json:{...d,status:ok?'DRAFT_ONLY':'NEEDS_HUMAN_REVIEW',review_required:!ok,reason:ok?'Owner-approved transfer draft':'Transfer destination/owner approval missing',action_draft:ok?{transfer_to:d.transfer_destination,owner:d.owner,call_back_note:'Draft only; do not connect or call'}:null}}];",
      'site-score': "const a=d.analyzer_output||{}; const score=Number(a.score); const threshold=Number(d.threshold??45); const facts=a.data||{}; const hasIdentity=Boolean(facts.business_name&&(facts.phone||(Array.isArray(facts.emails)&&facts.emails.length))); const ok=a.ok===true&&hasIdentity&&Number.isFinite(score)&&score>=0&&score<=100&&Number.isFinite(threshold)&&score<=threshold&&d.authorized_public_url===true; return [{json:{...d,status:ok?'DRAFT_ONLY':'NEEDS_HUMAN_REVIEW',review_required:!ok,reason:ok?'Authorized analyzer output is at or below the weak-site threshold':'Require authorized source, valid essentials, and analyzer score <= threshold',action_draft:ok?{preview:'DRAFT_ONLY',watermark:'NOT THE LIVE SITE',source_facts:facts}:null}}];",
      'site-outreach': "const c=Number(d.daily_count||0); const ok=d.opted_out!==true&&d.sender_name&&d.sender_email&&d.physical_address&&c<Number(d.daily_capacity||5)&&d.duplicate_found!==true&&d.human_review===true&&d.real_identity_confirmed===true; return [{json:{...d,status:ok?'DRAFT_ONLY':'NEEDS_HUMAN_REVIEW',review_required:!ok,reason:ok?'Opt-out, capacity, identity, address, and review gates passed':'No contact: review identity/address/opt-out/capacity and approve',action_draft:ok?{method:'DRAFT_ONLY',message:'Personalized opt-out-aware draft; no email or contact form submission'}:null}}];",
      'gold-rates': "const r=d.rate_source||{}; const ok=r.as_of_date===d.as_of_date&&r.owner_verified===true&&r.gold_22k!=null&&r.gold_24k!=null&&r.silver!=null; return [{json:{...d,status:ok?'DRAFT_ONLY':'NEEDS_HUMAN_REVIEW',review_required:!ok,reason:ok?'Rates are fresh for explicit as_of_date and owner verified':'Rate source is stale, incomplete, or not owner verified',action_draft:ok?{as_of_date:d.as_of_date,metadata:{named_rate_review:'10:30 Asia/Kolkata',timezone:'Asia/Kolkata'},rates:{gold_22k:r.gold_22k,gold_24k:r.gold_24k,silver:r.silver},broadcast:'DRAFT_ONLY; no scheduled send'}:null}}];",
      'gold-estimate': "const r=d.rate_source||{}, s=d.estimate_settings||{}; const weight=Number(d.weight_grams), rate=Number(r.gold_22k), charge=Number(s.making_charge_value), taxRate=Number(s.tax_rate); const validNumbers=[weight,rate,charge,taxRate].every(Number.isFinite)&&weight>0&&rate>0&&charge>=0&&taxRate>=0&&taxRate<=100; const validType=['percent','flat'].includes(s.making_charge_type)&&s.tax_basis==='metal_and_making'; const metal=weight*rate; const making=s.making_charge_type==='percent'?metal*charge/100:charge; const tax=taxRate/100*(metal+making); const ok=validNumbers&&validType&&Number.isFinite(metal+making+tax)&&r.owner_verified===true&&s.owner_verified===true&&Boolean(d.as_of_date)&&d.as_of_date===r.as_of_date; return [{json:{...d,status:ok?'DRAFT_ONLY':'NEEDS_HUMAN_REVIEW',review_required:!ok,reason:ok?'Deterministic estimate from explicit owner-verified source numerics and tax basis':'Require current approved rates, valid positive weight, nonnegative charges, explicit method and approved tax basis',action_draft:ok?{estimate:{as_of_date:d.as_of_date,metal_value:metal,making_charge:making,tax_amount:tax,total:metal+making+tax},tax_note:'Showroom-provided tax settings; indicative draft only, not tax advice or a binding quote'}:null}}];",
      'gold-reminder': "const dateOnly=x=>typeof x==='string'&&/^\\d{4}-\\d{2}-\\d{2}$/.test(x); const valid=dateOnly(d.next_due)&&dateOnly(d.reference_date); const due=valid?Date.parse(d.next_due+'T00:00:00Z'):NaN, ref=valid?Date.parse(d.reference_date+'T00:00:00Z'):NaN; const days=(due-ref)/86400000; const opted=d.opted_in===true||String(d.opted_in).toLowerCase()==='yes'; const ok=valid&&Number.isFinite(days)&&opted&&days===2&&d.reminder_hour==='11:00'&&d.timezone==='Asia/Kolkata'&&d.duplicate_found!==true; return [{json:{...d,status:ok?'DRAFT_ONLY':'NEEDS_HUMAN_REVIEW',review_required:!ok,reason:ok?'Opt-in, exact two-calendar-day window, timezone, and duplicate checks passed':'Reminder requires opted_in yes, exact date-only 2 days, 11:00 Asia/Kolkata, no duplicate',action_draft:ok?{reminder:'DRAFT_ONLY',due:d.next_due}:null}}];",
      'gold-visit': "const ok=d.staff_approval===true&&d.customer_name&&d.requested_slot&&d.owner; return [{json:{...d,status:ok?'DRAFT_ONLY':'NEEDS_HUMAN_REVIEW',review_required:!ok,reason:ok?'Staff-approved showroom visit draft':'Visit requires named owner, slot, and staff approval',action_draft:ok?{visit:{customer:d.customer_name,slot:d.requested_slot,owner:d.owner},send:false}:null}}];",
      'ca-support': "const missing=['client_id','request','owner'].filter(k=>!String(d[k]||'').trim()); const sensitive=/advice|file|tax position|payment/i.test(String(d.request||'')); const ok=!missing.length&&!sensitive&&d.partner_approval===true; return [{json:{...d,status:ok?'DRAFT_ONLY':'NEEDS_HUMAN_REVIEW',review_required:!ok,reason:ok?'Administrative support draft approved':'Missing fields, sensitive professional request, or partner approval',action_draft:ok?{reply:'Draft only: the firm team will review and respond.',log_table:'Query_Log'}:null}}];",
      'ca-docs': "const ok=d.document_status&&d.client_id&&d.owner&&d.deadline_approved===true&&d.partner_approval===true; return [{json:{...d,status:ok?'DRAFT_ONLY':'NEEDS_HUMAN_REVIEW',review_required:!ok,reason:ok?'Document checklist/status and approved deadline draft':'Document status, approved deadline, or partner approval missing',action_draft:ok?{table:'Documents_Tracker',status:d.document_status,deadline:d.deadline,request:'DRAFT_ONLY'}:null}}];",
      'ca-invoice': "const ok=d.invoice_id&&d.invoice_status&&d.client_id&&d.partner_approval===true; return [{json:{...d,status:ok?'DRAFT_ONLY':'NEEDS_HUMAN_REVIEW',review_required:!ok,reason:ok?'Invoice-status follow-up draft approved':'Invoice facts or partner approval missing',action_draft:ok?{table:'Invoices',message:'Draft only: please review invoice status with the firm.',payment:false}:null}}];",
      'ca-exception': "const ok=d.exception_type&&d.owner&&d.partner_approval===true; return [{json:{...d,status:ok?'DRAFT_ONLY':'NEEDS_HUMAN_REVIEW',review_required:!ok,reason:ok?'Partner escalation draft approved':'Partner approval or exception owner missing',action_draft:ok?{table:'Error_Log',exception:d.exception_type,filing:false,advice:false}:null}}];"
    }
    return common + bodies[kind]
def make_wf(title, slug, payload, kind):
    ids=[str(uuid.uuid4()) for _ in range(4)]; names=['Manual Trigger','Prepare synthetic input','Validate safety gates','Draft action / human handoff']
    nodes=[{'parameters':{},'id':ids[0],'name':names[0],'type':'n8n-nodes-base.manualTrigger','typeVersion':1,'position':[0,0]}, {'parameters':{'mode':'runOnceForAllItems','jsCode':js_prepare(payload,slug)},'id':ids[1],'name':names[1],'type':'n8n-nodes-base.code','typeVersion':2,'position':[260,0]}, {'parameters':{'mode':'runOnceForAllItems','jsCode':js_logic('realestate-normalize' if kind=='realestate-normalize' else kind)},'id':ids[2],'name':names[2],'type':'n8n-nodes-base.code','typeVersion':2,'position':[560,0]}, {'parameters':{'mode':'runOnceForAllItems','jsCode':"const d=$input.first().json; const v=d._validation||d; return [{json:{...d,status:v.status||'NEEDS_HUMAN_REVIEW',review_required:v.review_required!==false,reason:v.reason||'Draft only',action_draft:v.action_draft||d.action_draft||null,correlation_id:d.correlation_id}}];"},'id':ids[3],'name':names[3],'type':'n8n-nodes-base.code','typeVersion':2,'position':[880,0]}]
    return {'name':title,'nodes':nodes,'connections':{names[0]:{'main':[[{'node':names[1],'type':'main','index':0}]]},names[1]:{'main':[[{'node':names[2],'type':'main','index':0}]]},names[2]:{'main':[[{'node':names[3],'type':'main','index':0}]]}},'pinData':{},'active':False,'settings':{'executionOrder':'v1'},'versionId':str(uuid.uuid4()),'meta':{'templateCredsSetupCompleted':False},'tags':[]}

def base_api(names): return {'enabled':False,'providers':[{'name':n,'docs_url':u,'credential_required':True,'key_value_included':False} for n,u in names],'rules':['Use client-owned credentials in n8n Credentials only.','No live endpoint, send, filing, payment, booking, hosting, or scheduler is included.']}
def base_config(kind): return {'enabled':False,'client':{'business_name':'','human_owner':'','timezone':'','country':'','provider_names':[]},'workflow':{'require_human_approval':True,'allowed_actions':['draft_only'],'daily_capacity':5,'quality_score_threshold':45},'credentials':{'values_excluded':True},'kit':kind}

def specs():
    return {
'realestate-lead-desk':('Real Estate Lead-to-Viewing Desk','realestate',[('channel-normalization','Normalize Meta, WhatsApp, and voice lead payload',{'source':'whatsapp','name':'Demo Buyer','contact':'+15550001001','enquiry_text':'2 bedroom near transit','opt_out':False,'correlation_id':'DEMO-RE-1'},'realestate-normalize'),('broker-viewing','Broker viewing draft from confirmed slot',{'lead_validated':True,'listing_source_confirmed':True,'viewing_slot':{'source_confirmed':True,'start':'2030-05-15T10:00:00Z'},'broker':'broker-demo','staff_approval':True,'correlation_id':'DEMO-RE-2'},'realestate-viewing'),('followup-guard','Opt-out and capped repeat follow-up draft',{'followup_count':1,'max_followups':3,'opt_out':False,'duplicate_found':False,'correlation_id':'DEMO-RE-3'},'realestate-followup')]),
'voice-front-desk':('Voice Front Desk Starter','voice',[('call-intake','Provider summary, language, consent, and disclosure intake',{'provider_event_id':'CALL-DEMO-1','summary':'Caller asks for opening hours','language':'en-IN','consent_status':'granted','disclosure_confirmed':True,'owner':'front-desk','correlation_id':'DEMO-VOICE-1'},'voice-intake'),('owner-transfer','Owner transfer draft',{'transfer_destination':'front-desk-queue','owner':'manager-demo','transfer_approval':True,'correlation_id':'DEMO-VOICE-2'},'voice-transfer')]),
'local-site-leadgen':('Local Website Audit & Lead Engine','leadgen',[('site-score-preview','Analyzer score threshold and watermarked preview draft',{'authorized_public_url':True,'threshold':45,'analyzer_output':{'ok':True,'score':42,'data':{'business_name':'Demo Studio','phone':'+15550001002','emails':[],'services':['demo service']}},'correlation_id':'DEMO-SITE-1'},'site-score'),('outreach-review','Identity, address, capacity, opt-out, and review gate',{'daily_count':0,'daily_capacity':5,'opted_out':False,'sender_name':'Demo Sender','sender_email':'sender@example.test','physical_address':'1 Demo Street','human_review':True,'real_identity_confirmed':True,'correlation_id':'DEMO-SITE-2'},'site-outreach')]),
'gold-showroom':('Gold Showroom AI Desk','gold',[('daily-rates','Fresh owner-verified rate draft',{'as_of_date':'2030-01-15','rate_source':{'as_of_date':'2030-01-15','gold_22k':6500,'gold_24k':7100,'silver':80,'owner_verified':True},'named_rate_review':'10:30 Asia/Kolkata','correlation_id':'DEMO-GOLD-1'},'gold-rates'),('scheme-reminder','Exact two-day opt-in scheme reminder at 11:00 Asia/Kolkata',{'reference_date':'2030-01-15','next_due':'2030-01-17','opted_in':True,'reminder_hour':'11:00','timezone':'Asia/Kolkata','duplicate_found':False,'correlation_id':'DEMO-GOLD-2'},'gold-reminder'),('showroom-visit','Staff-approved visit request draft',{'customer_name':'Demo Customer','requested_slot':'2030-01-18T11:30:00+05:30','owner':'showroom-staff','staff_approval':True,'correlation_id':'DEMO-GOLD-3'},'gold-visit'),('estimate-slip','Deterministic estimate from rate, making charge, and tax settings',{'as_of_date':'2030-01-15','weight_grams':10,'rate_source':{'as_of_date':'2030-01-15','gold_22k':6500,'owner_verified':True},'estimate_settings':{'making_charge_type':'percent','making_charge_value':10,'tax_rate':1.5,'tax_basis':'metal_and_making','owner_verified':True},'correlation_id':'DEMO-GOLD-4'},'gold-estimate')]),
'ca-practice':('CA Practice Operations Desk','ca',[('support-newlead','Support/new-lead administrative draft',{'client_id':'CLIENT-DEMO-1','request':'Please confirm which document is outstanding','owner':'team-demo','partner_approval':True,'correlation_id':'DEMO-CA-1'},'ca-support'),('documents-deadline','Document tracker and approved deadline draft',{'client_id':'CLIENT-DEMO-1','document_status':'missing bank statement','deadline':'2030-03-31','deadline_approved':True,'owner':'team-demo','partner_approval':True,'correlation_id':'DEMO-CA-2'},'ca-docs'),('invoice-status','Invoice status follow-up draft',{'client_id':'CLIENT-DEMO-1','invoice_id':'INV-DEMO-1','invoice_status':'open','partner_approval':True,'correlation_id':'DEMO-CA-3'},'ca-invoice'),('partner-exception','Partner exception escalation draft',{'exception_type':'missing source record','owner':'partner-demo','partner_approval':True,'correlation_id':'DEMO-CA-4'},'ca-exception')])}

def write_texts(folder, title, kind, rows):
    (folder/'README.md').write_text(COMMON.format(title=title),encoding='utf-8')
    (folder/'quick-start.md').write_text(f"# Quick start\n\n1. Keep **{kind}** inactive.\n2. Import one workflow and execute its synthetic Manual Trigger.\n3. Review validation, correlation ID, and the draft; nothing is sent or written.\n4. Fill client particulars and provider docs in `config-template.json` and `api-requirements.json`; never paste API keys.\n5. Obtain named human approval, source confirmation, privacy/security review, and durable idempotency before any production adapter.\n",encoding='utf-8')
    schemas={'input':{'type':'object','required':['correlation_id']},'output':{'status':['DRAFT_ONLY','NEEDS_HUMAN_REVIEW'],'review_required':'boolean','correlation_id':'string'},'kit':kind,'workflow_contracts':{r[0]:{'draft_only':True,'human_approval_required':True} for r in rows}}
    dump(folder/'schemas.json',schemas); dump(folder/'sample-payloads.json',{r[0]:r[2] for r in rows}); dump(folder/'tests.json',{'cases':[{'id':r[0]+'-happy','select':r[0],'expect':'inactive, correlation_id preserved, DRAFT_ONLY or NEEDS_HUMAN_REVIEW, no external action'} for r in rows]+[{'id':'missing-or-stale-gate','expect':'NEEDS_HUMAN_REVIEW and no draft send'}]})
    (folder/'prompts.md').write_text('# Configurable prompt\n\nUse only supplied source facts. Preserve correlation_id. Never invent slots, rates, deadlines, identity, contact details, tax advice, filings, payments, or provider results. Return `NEEDS_HUMAN_REVIEW` for missing, conflicting, stale, opt-out, duplicate, unapproved, or sensitive data. Produce drafts only; a named human must approve every consequential action.\n\n## Workflow intents\n\n'+ '\n'.join(f'- **{r[0]}**: {r[1]}' for r in rows)+'\n',encoding='utf-8')

def main():
    TMP.mkdir(exist_ok=True)
    if SRC.exists():
        shutil.rmtree(TMP/'leadgen-engine-export',ignore_errors=True); import zipfile
        with zipfile.ZipFile(SRC) as z:
            for info in z.infolist():
                part=Path(info.filename)
                if part.is_absolute() or '..' in part.parts or info.file_size>2_000_000: raise ValueError('Unsafe source archive member')
            z.extractall(TMP)
    inv={}
    old=OUT/'KIT_INVENTORY.json'
    if old.exists():
        try: inv=json.loads(old.read_text())
        except Exception: inv={}
    for slug,(title,kind,rows) in specs().items():
        folder=OUT/slug; wfdir=folder/'workflows'; shutil.rmtree(folder,ignore_errors=True); wfdir.mkdir(parents=True)
        for ws,title2,payload,wkind in rows: dump(wfdir/(ws+'.json'),make_wf(title2,ws,payload,wkind))
        write_texts(folder,title,kind,rows)
        dump(folder/'api-requirements.json',base_api([('Google Sheets','https://developers.google.com/sheets/api'),('Meta WhatsApp Business','https://developers.facebook.com/docs/whatsapp'),('OpenAI-compatible provider','https://platform.openai.com/docs')]))
        dump(folder/'config-template.json',base_config(kind))
        if slug=='local-site-leadgen':
            src=TMP/'leadgen-engine-export'; shutil.copy2(src/'website-analyzer.py',folder/'website-analyzer.py'); dump(folder/'data-models.json',json.loads((src/'schemas.json').read_text()))
            shutil.copy2(src/'workflows.jsonc',folder/'original-reference-workflows.jsonc')
            (folder/'pipeline-prompt.md').write_text('# Revised pipeline prompt\n\nAnalyze only a client-supplied authorized public URL. Use analyzer output and source facts; threshold is 45 and daily cap is 5 by default. Prepare a clearly watermarked preview draft only. Require human review before hosting, contact, or email. Never use an automatic fallback contact form; do not discover or infer contact details. Preserve real identity, sender address, and opt-out handling. The supplied Base44 schedule is reference-only, paused, and not an import.\n',encoding='utf-8')
            (folder/'email-template.md').write_text('# Revised outreach draft\n\nPrepare one human-reviewed, opt-out-aware draft only. Reference only analyzer facts, include sender identity and physical address, and include a clear opt-out line. Do not send email, submit contact forms, host a preview, or invent business details.\n',encoding='utf-8')
        elif slug=='gold-showroom':
            dump(folder/'data-models.json',{'Rates':{'columns':['date','gold_22k','gold_24k','silver']},'Subscribers':{'columns':['name','phone','opted_in']},'Scheme':{'columns':['name','phone','monthly_amount','paid_months','total_months','next_due']},'Visits':{'columns':['visit_id','name','phone','requested_slot','owner','staff_approval'],'note':'Aria-defined template; supplied source did not expose Visits columns.'}})
        elif slug=='ca-practice':
            dump(folder/'data-models.json',{'Clients':{'columns':['client_id','name','owner','consent_status']},'Leads':{'columns':['lead_id','name','source','owner','status']},'Documents_Tracker':{'columns':['client_id','document','status','due_date','owner']},'Compliance_Calendar':{'columns':['client_id','item','deadline','approved','owner']},'Invoices':{'columns':['invoice_id','client_id','status','amount','owner']},'Query_Log':{'columns':['query_id','client_id','request','owner','partner_approval']},'Error_Log':{'columns':['error_id','type','record_id','owner','resolved']},'source_note':'Seven table names are source-supported; these minimal columns are Aria-defined administrative template fields, not an exact copy of the original schema. Map firm-owned actual columns. No advice, filing or payment.'})
        inv[slug]={'workflows':[f'workflows/{r[0]}.json' for r in rows],'files':['README.md','prompts.md','schemas.json','sample-payloads.json','tests.json','quick-start.md','api-requirements.json','config-template.json']}
    dump(old,inv); print(f'generated {len(specs())} extended kits; inventory has {len(inv)} kits')
if __name__=='__main__': main()
